import re,sys,glob,os,collections
files=sys.argv[1:]
res=collections.defaultdict(lambda: collections.defaultdict(set))
fn=re.compile(r'\b((?:__|atomic|wmma::|memcpy_async|cuda::)[A-Za-z0-9_]+|__pipeline_\w+|__nv_\w+)\s*\(')
for f in files:
    b=os.path.basename(f); m=re.match(r'sm_(\d+)',b); base=int(m.group(1))*10 if m else 0
    stack=[]
    for line in open(f,errors='ignore'):
        s=line.strip()
        if s.startswith('#if'):
            g=re.search(r'__CUDA_ARCH__\s*>=\s*(\d+)',s)
            neg=re.search(r'__CUDA_ARCH__\s*<\s*(\d+)',s) and not g
            stack.append(('ge',int(g.group(1))) if g else (('lt',0) if neg else None)); continue
        if s.startswith('#elif'):
            g=re.search(r'__CUDA_ARCH__\s*>=\s*(\d+)',s); stack[-1]=('ge',int(g.group(1))) if g else None; continue
        if s.startswith('#else'):
            if stack and stack[-1] and stack[-1][0]=='ge': stack[-1]=('lt',0)
            elif stack and stack[-1] and stack[-1][0]=='lt': stack[-1]=None
            continue
        if s.startswith('#endif'):
            stack and stack.pop(); continue
        if s.startswith(('//','*','/*','#')): continue
        if any(x and x[0]=='lt' for x in stack): continue
        if not re.search(r'__device__|_DECL__|__CUDA_FP16_DECL__|__CUDA_BF16_DECL__|__CUDA_HOSTDEVICE|_QUALIFIER|__DEF_IF_HOST',s): continue
        for n in fn.findall(s):
            a=max([base]+[x[1] for x in stack if x and x[0]=='ge'])
            res[a][b].add(n)
for a in sorted(res):
    print(f'### arch>={a}')
    for b in sorted(res[a]): print(f'  {b}: {" ".join(sorted(res[a][b]))}')
EOF
