#include <cstdint>
// V0: ollama37 fallback (common.cuh:563-565)
__device__ __forceinline__ int dp_v0(int a, int b, int c) {
    const int8_t * a8 = (const int8_t *) &a; const int8_t * b8 = (const int8_t *) &b;
    return c + a8[0]*b8[0] + a8[1]*b8[1] + a8[2]*b8[2] + a8[3]*b8[3];
}
// V1: PTX scalar video multiply-add with byte select (vmad, sm_20+)
__device__ __forceinline__ int dp_v1(int a, int b, int c) {
    asm("vmad.s32.s32.s32 %0, %1.b0, %2.b0, %0;\n\t"
        "vmad.s32.s32.s32 %0, %1.b1, %2.b1, %0;\n\t"
        "vmad.s32.s32.s32 %0, %1.b2, %2.b2, %0;\n\t"
        "vmad.s32.s32.s32 %0, %1.b3, %2.b3, %0;" : "+r"(c) : "r"(a), "r"(b));
    return c;
}
// V2: sign-extend with cvt.s32.s8 (I2I, 128/clk on cc3.x) instead of BFE (32/clk)
__device__ __forceinline__ int sx8(int x) { int r; asm("cvt.s32.s8 %0, %1;" : "=r"(r) : "r"(x)); return r; }
__device__ __forceinline__ int dp_v2(int a, int b, int c) {
    c += sx8(a) * sx8(b); c += sx8(a >> 8) * sx8(b >> 8);
    c += sx8(a >> 16) * sx8(b >> 16); c += (a >> 24) * (b >> 24);
    return c;
}
#define KERNEL(V) \
__global__ void k_##V(const int * __restrict__ x, const int * __restrict__ y, int * __restrict__ out) { \
    int a[8], b[8]; _Pragma("unroll") for (int i = 0; i < 8; ++i) { a[i] = x[threadIdx.x*8+i]; b[i] = y[threadIdx.x*8+i]; } \
    int s = 0; _Pragma("unroll") for (int i = 0; i < 8; ++i) s = dp_##V(a[i], b[i], s); \
    out[threadIdx.x] = s; }
KERNEL(v0) KERNEL(v1) KERNEL(v2)
EOF
